package br.com.equilibra.goal.domain;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*; import java.util.UUID;
@Entity @Table(name="goal_contributions") public class GoalContribution { @Id @Column(length=36,updatable=false) private String id; @Column(name="owner_id",nullable=false,updatable=false) private String ownerId; @Column(name="goal_id",nullable=false,updatable=false) private String goalId; @Column(nullable=false,precision=19,scale=2) private BigDecimal amount; @Column(name="occurred_at",nullable=false) private Instant occurredAt; @Column(length=1000) private String note; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt; @Version private Long version; protected GoalContribution(){} public GoalContribution(String owner,String goal,BigDecimal amount,Instant occurred,String note){id=UUID.randomUUID().toString();ownerId=owner;goalId=goal;if(amount==null||amount.signum()<=0||amount.scale()>2)throw new IllegalArgumentException("amount is invalid");this.amount=amount.setScale(2);occurredAt=occurred;this.note=note;} @PrePersist void create(){createdAt=Instant.now();} public String getId(){return id;} public String getOwnerId(){return ownerId;} public String getGoalId(){return goalId;} public BigDecimal getAmount(){return amount;} public Instant getOccurredAt(){return occurredAt;} public String getNote(){return note;} public Instant getCreatedAt(){return createdAt;} }
